def refine_close_callback(call):
        _safe_answer_refine_callback(bot, call)
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            bot.send_message(call.message.chat.id, "✅ Меню заточки закрито.")

def _db():

    import db

    return db

def _call_legacy(name, *args, **kwargs):

    db = _db()

    legacy_name = f"_legacy_equipment_ro_v1_{name}"

    legacy = getattr(db, legacy_name, None)



    if legacy is None:

        raise AttributeError(f"Legacy equipment read-only function not found: {legacy_name}")



    return legacy(*args, **kwargs)

def is_armor_slot(slot_key):

    """Return True only for the six physical armor slots."""

    return str(slot_key or "") in _ARMOR_SLOT_KEYS

def can_equip_item_by_class(user_id, item_info):

    db = _db()



    if not item_info:

        return {

            "success": False,

            "message": "❌ Предмет не знайдено."

        }



    if item_info.get("category") != "equipment":

        return {

            "success": True,

            "message": ""

        }



    class_key = db.get_character_class(user_id)

    if not class_key:

        return {

            "success": False,

            "message": "❌ Спочатку обери клас персонажа."

        }



    checks = (

        db.check_armor_compatibility_for_class,

        db.check_main_hand_compatibility_for_class,

        db.check_off_hand_compatibility_for_class,

    )

    for check in checks:

        result = check(class_key, item_info)

        if not result["success"]:

            return result



    result = db.check_two_handed_conflict_for_equip(user_id, item_info)

    if not result["success"]:

        return result



    return {

        "success": True,

        "message": ""

    }

def can_equip_inventory_item_by_class(user_id, inventory_id):

    db = _db()

    item_info = db.get_item_classification_by_inventory_id(inventory_id)

    return can_equip_item_by_class(user_id, item_info)

def is_inventory_item_class_compatible(user_id, inventory_id):

    result = can_equip_inventory_item_by_class(user_id, inventory_id)

    return bool(result.get("success"))

def _call_legacy_write(name, *args, **kwargs):

    db = _db()

    legacy_name = f'_legacy_equipment_write_v1_{name}'

    legacy = getattr(db, legacy_name, None)

    if legacy is None:

        # Fallback for functions that may already have been captured by read-only facade naming.

        legacy = getattr(db, f'_legacy_equipment_ro_v1_{name}', None)

    if legacy is None:

        raise AttributeError(f'Legacy equipment write function not found: {legacy_name}')

    return legacy(*args, **kwargs)

def _extract_equipment_user_id(args, kwargs):

    if 'user_id' in kwargs:

        return kwargs.get('user_id')

    if args:

        return args[0]

    return None

def _sync_equipment_player_hp(user_id):

    if user_id is None:

        return None

    try:

        db = _db()

        sync = getattr(db, 'sync_user_max_hp', None)

        if sync:

            try:

                return sync(user_id, heal_to_full=False)

            except TypeError:

                return sync(user_id)

    except Exception:

        return None

    return None

def _call_legacy_repair_durability_sell(name, *args, **kwargs):

    db = _db()

    legacy_name = f'_legacy_equipment_rds_v1_{name}'

    legacy = getattr(db, legacy_name, None)

    if legacy is None:

        legacy = getattr(db, f'_legacy_equipment_write_v1_{name}', None)

    if legacy is None:

        legacy = getattr(db, f'_legacy_equipment_ro_v1_{name}', None)

    if legacy is None:

        raise AttributeError(f'Legacy equipment repair/durability/sell function not found: {legacy_name}')

    return legacy(*args, **kwargs)

