    total = len(collected)
    if total == 0:
        page = 0
    elif page * page_size >= total:
        page = (total - 1) // page_size
    start = page * page_size
    return {
        "success": True,
        "trade_id": int(trade_id),
        "category": category,
        "page": page,
        "page_size": page_size,
        "total": total,
        "items": collected[start:start + page_size],
        "has_previous": page > 0,
        "has_next": start + page_size < total,
    }

