 return BattleActor(character_class,s.level,hp,s.max_hp,s.attack,s.magic_attack,s.pdef,s.mdef,s.dex,s.wis,s.sta,s.attack_type,s.weapon_min_damage,s.weapon_max_damage,s.resource_type,resource,max_resource)

def get_bag_capacity(user_id):
    cursor.execute("""
    SELECT bag_slots
    FROM users
    WHERE user_id=?
    """, (user_id,))

    row = cursor.fetchone()

    if not row or row[0] is None:
        return DEFAULT_BAG_SLOTS

    try:
        capacity = int(row[0] or DEFAULT_BAG_SLOTS)
    except Exception:
        capacity = DEFAULT_BAG_SLOTS
    return max(DEFAULT_BAG_SLOTS, capacity)

